-- State transitions declared for Subscription: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION subscription.subscriptions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'cancelled'), ('active', 'expired'), ('active', 'past_due'), ('active', 'paused'), ('cancelled', 'expired'), ('past_due', 'active'), ('past_due', 'cancelled'), ('paused', 'active'), ('paused', 'cancelled'), ('trial', 'active'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: subscriptions.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_subscriptions__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS subscriptions_status_transition_check ON subscription.subscriptions;
CREATE TRIGGER subscriptions_status_transition_check
    BEFORE UPDATE OF "status" ON subscription.subscriptions
    FOR EACH ROW EXECUTE FUNCTION subscription.subscriptions_status_transition_check();
